function getSavedThemeCSS() {
  if (typeof globalThis === "undefined" || !("localStorage" in globalThis)) {
    return "";
  }

  try {
    return globalThis.localStorage?.getItem("architect-theme-css") || "";
  } catch {
    return "";
  }
}

